python3 - <<'EOF'
# 1. /arena route in webapp/main.py (after home route)
p = "webapp/main.py"
s = open(p).read()
s = s.replace(
    '@app.get("/walkforward", response_class=HTMLResponse)\n'
    'async def walkforward_form(request: Request) -> HTMLResponse:',
    '@app.get("/arena", response_class=HTMLResponse)\n'
    'async def arena_view(request: Request) -> HTMLResponse:\n'
    '    """Read-only arena comparison — the lab theme\'s showcase page."""\n'
    '    db_path = os.environ.get("ARENA_DB", str(Path(os.getcwd()) / "arena_state" / "arena.db"))\n'
    '    rows: List[Dict[str, Any]] = []\n'
    '    error = None\n'
    '    if Path(db_path).exists():\n'
    '        try:\n'
    '            # Local imports: keep webapp startup light; these pull pandas etc.\n'
    '            from analyze_equity import compare_strategies\n'
    '            from strategy_arena import ArenaState\n'
    '\n'
    '            table = compare_strategies(ArenaState(db_path).conn)\n'
    '            rows = table.where(table.notna(), None).to_dict(orient="records")\n'
    '        except Exception as exc:  # a broken DB should render, not 500\n'
    '            error = f"Could not read arena DB: {exc}"\n'
    '    return templates.TemplateResponse(\n'
    '        "arena.html",\n'
    '        {"request": request, "title": "Arena Comparison", "rows": rows,\n'
    '         "db_path": db_path, "error": error, "message": None},\n'
    '    )\n'
    '\n'
    '\n'
    '@app.get("/walkforward", response_class=HTMLResponse)\n'
    'async def walkforward_form(request: Request) -> HTMLResponse:')
open(p, "w").write(s)

# 2. classic-side additive styles (metric cards + badges shared shape)
css = open("webapp/static/style.css").read()
css += """

/* --- Additive: metric cards + status badges (both themes; lab restyles) --- */
.metric-row {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin: 1rem 0 1.5rem;
}
.metric-card {
  border: 1px solid #d0d4dc;
  border-radius: 6px;
  padding: 0.7rem 1rem;
  min-width: 150px;
}
.metric-label { font-size: 0.8rem; color: #667; }
.metric-value { font-size: 1.5rem; font-weight: 600; }
.metric-delta.up   { color: #0a7f3f; font-size: 0.85rem; }
.metric-delta.down { color: #b3261e; font-size: 0.85rem; }
.badge {
  display: inline-block;
  padding: 0.15rem 0.6rem;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 700;
}
.badge.status-pass      { background: #e2f5e9; color: #0a7f3f; }
.badge.status-probation { background: #fdf0dd; color: #a06a00; }
.badge.status-paused    { background: #fde3e1; color: #b3261e; }
.badge.status-excluded,
.badge.status-reference { background: #e8eaee; color: #59606d; }
.badge.status-research  { background: #e2ecfd; color: #2a5db0; }
.theme-toggle { font-size: 0.8rem; color: #ccd5e0; margin-left: auto; }
"""
open("webapp/static/style.css", "w").write(css)

# 3. drop the stray theme-classic selector comment from theme-lab.css
lab = open("webapp/static/theme-lab.css").read()
lab = lab.replace(
    "body.theme-lab .badge,\nbody.theme-classic .badge { /* shape shared; colors below */\n"
    "  display: inline-block;\n  padding: 0.15rem 0.6rem;\n  border-radius: 999px;\n"
    "  font-size: 0.78rem;\n  font-weight: 700;\n}\n",
    "/* badge shape lives in style.css (shared); lab-specific colors below */\n")
open("webapp/static/theme-lab.css", "w").write(lab)
print("route + styles applied")
EOF
uv run python -c "import webapp.main; print('webapp imports ok')"

